    caption: '도면을 보면 M6 볼트 자리 구멍이 Ø6.4~6.6쯤으로 적혀 있어요. 볼트보다 살짝 큰 \'여유 구멍\'이죠. 처음엔 \'딱 맞게 뚫으면 더 정확하지 않나?\' 싶으실 거예요.\n\n그런데 구멍이 딱 맞으면 작은 가공 오차에도 볼트가 안 들어가요. 그래서 여유를 주고, 정확한 위치는 다른 부품에 맡깁니다. 바로 다월핀이에요. 여유 구멍은 조립 오차를 흡수하고, 다월핀과 정밀 구멍은 위치를 고정하고, 볼트는 두 부품을 꽉 조이기만 해요. 역할을 셋으로 나눈 거죠.\n\n볼트로 위치까지 잡으려 하면 어떻게 될까요? 볼트는 여유 구멍 안에서 흔들리니 조일 때마다 위치가 조금씩 달라져요. 분해했다 다시 조립해도 같은 자리에 와야 한다면, 설계할 때 핀 구멍 두 개를 꼭 넣어 주세요. 핀 구멍은 볼트 구멍과 공차가 다르니 도면에 따로 표기해 주시면 됩니다.\n\n정리하면, 조이는 건 볼트, 맞추는 건 핀.\n\n볼트로 위치 잡으려다 고생한 경험, 있으신가요?',
