    caption: '플라스틱 자를 눕혀서 누르면 쉽게 휘는데, 세워서 누르면 꿈쩍도 안 해요. 같은 자인데 말이죠. 각봉이나 프레임도 마찬가지예요.\n\n이유는 휨 강성이 높이의 세제곱에 비례하기 때문이에요. 휨에 버티는 힘은 단면 2차 모멘트 I = b·h³/12에 비례하는데, 높이 h가 세제곱으로 들어가요. 폭과 높이를 바꾸면 h³가 바뀌니 방향만으로 강성이 수십 배 차이 나죠. 재료도 무게도 그대로인데요. 중심에서 먼 살이 더 버티기 때문에, 살을 멀리 세워 놓을수록 유리한 거예요.\n\n선반 받침이나 건물의 보가 세로로 길쭉한 것도 이 때문이에요. 프레임을 설계하실 땐 하중이 오는 방향으로 단면의 긴 쪽을 세워 배치해 주세요. 두껍게 만드는 것보다 방향을 바꾸는 쪽이 재료를 안 늘리고도 훨씬 강해집니다.\n\n정리하면, 같은 재료라도 세우면 강해진다.\n\n자를 눕혀서 휘어 본 기억, 다들 있으시죠?',
