    caption: '도면에 \'알루미늄\'이라고만 적어서 견적을 넣으면, 업체마다 값이 두 배 가까이 차이 나는 경우가 있어요. 5052로 봤는지, 6061로 봤는지, 7075로 봤는지가 서로 달랐던 거죠.\n\n알루미늄은 어떤 원소를 섞었느냐로 계열이 나뉘고, 그걸 네 자리 번호로 표시해요. 번호마다 강도·내식성·가공성이 달라서 쓰임새도, 가격도 함께 달라집니다. 5052는 내식성과 성형·용접이 좋아 판재 케이스에, 6061은 강도·가공·내식의 균형이 좋아 가장 흔하게, 7075는 항공용 고강도지만 비싸고 용접이 난감해요.\n\n가공 부품이라면 대부분 6061-T6면 충분합니다. \'튼튼하게\'만 보고 7075를 고르면 비용만 올라가는 경우가 많아요. 주문하실 땐 재질 번호를 직접 정하기 어려우시면, 쓰는 환경과 받는 힘을 알려주시면 알맞은 재질을 골라드릴 수 있어요.\n\n정리하면, 알루미늄은 \'알루미늄\'이 아니라 번호로 고르는 재료예요.\n\n여러분이 쓰고 있는 알루미늄 부품, 몇 번이었는지 확인해보신 적 있나요?',
