    caption: '\'스테인리스니까 녹 안 슬면 다 똑같겠지\' 하고 넘기기 쉬운데, 가공 현장에선 303, 304, 316을 완전히 다른 재료처럼 다뤄요. 깎을 때 나오는 칩 모양부터 다르거든요.\n\n차이는 섞인 원소 하나에서 나와요. 303은 황(S)을 더해 칩이 잘 끊기는 쾌삭재라 가공은 쉽지만 내식성은 낮아요. 316은 몰리브덴을 더해 바닷물이나 약품에 강한 대신 가장 비싸고요. 304는 그 사이의 범용 재질인데, 끈적한 성질 때문에 공구 마모가 커서 가공 부담이 있는 편이에요.\n\n실내나 일반 환경이라면 304로 충분한 경우가 대부분이에요. 거기에 316을 쓰면 돈만 더 들죠. 반대로 선반 가공이 많은 소형 부품은 303이 단가에 유리해요. 그래서 주문하실 땐 재질 번호보다 \'어디에 쓰는 부품인지\'를 꼭 함께 알려주세요.\n\n한 줄로 정리하면, 스테인리스는 쓰는 환경과 가공량으로 고르는 재료예요.\n\n내 부품은 304로 충분했을까요, 아니면 정말 316이 필요한 자리였을까요?',
