    caption: '고급 노트북이나 카메라 바디를 만져보면 보송한 무광 질감이 있죠. 가공 자국도 없고 지문도 잘 안 보여서 \'이건 어떻게 만든 거지?\' 싶어져요.\n\n비밀은 수많은 아주 작은 자국이에요. 유리알이나 알루미나 같은 미세 입자를 고압으로 표면에 쏘면, 작은 자국들이 겹치면서 고르게 거친 면이 돼요. 그러면 가공 자국이 사라지고 균일한 무광이 되고, 지문이나 잔흠도 눈에 덜 띄어요. 입자 크기를 바꾸면 거칠기도 조절할 수 있고요.\n\n알루미늄 부품에선 블라스트 뒤에 아노다이징을 하는 게 고급 질감의 공식이에요. 다만 공정이 하나 늘어나는 만큼 단가는 올라가요. 그래서 외관이 중요한 부품에만 \'블라스트+아노다이징\'으로 적어주시고, 보이지 않는 내부 부품은 생략하는 게 비용에 유리해요.\n\n정리하면, 무광의 비밀은 수많은 작은 자국이에요.\n\n무광 질감 제품이 왜 더 비싼지, 이제 감이 오시나요? ✨',
