    caption: '베어링을 보면 이름 대신 6205, 6304 같은 네 자리 숫자만 찍혀 있어요. 그런데 숙련자는 이 숫자만 보고 크기와 형식을 바로 알아내요.\n\n자리마다 뜻이 정해진 암호이기 때문이에요. 6205를 예로 들면 앞의 6은 형식(깊은홈 볼베어링), 2는 치수 계열(두께·외경 크기), 뒤의 05는 안지름 코드예요. 내경 코드는 04부터 5를 곱하면 되니까 05는 25mm, 06은 30mm가 되죠. 다만 00~03은 10·12·15·17mm로 예외예요.\n\n번호 뒤에 붙는 글자는 밀봉 방식이에요. ZZ는 양쪽 금속 실드, 2RS는 양쪽 고무 씰이라 먼지나 물이 닿는 곳이면 2RS가 맞아요. 베어링이 들어가는 부품을 설계하거나 주문하실 땐 숫자만이 아니라 뒤 접미사까지 꼭 적어주세요. 축 지름과 하우징 치수도 거기서 결정되니까요.\n\n정리하면, 베어링 번호는 보기만 해도 크기와 형식이 읽히도록 설계된 체계예요.\n\n여러분 장비 속 베어링 번호, 한번 읽어보실래요?',
