    caption: '버니어 캘리퍼스의 어미자 눈금은 1mm 간격이에요. 그런데 이 자 하나로 0.05mm 단위까지 읽어내죠. 돋보기도 없이요. 처음 보면 \'이게 어떻게 되지?\' 싶어요.\n\n비밀은 일부러 살짝 다르게 만든 눈금 간격에 있어요. 아들자(부척)의 눈금은 어미자(본척)보다 아주 조금 좁아요. 그래서 두 눈금이 딱 겹치는 자리가 한 칸씩 밀리면서 소수점을 알려주는 셈이에요. 읽는 법은 세 단계면 끝나요. 어미자에서 아들자 0 앞의 정수를 읽고, 아들자에서 어미자와 겹치는 눈금을 찾은 뒤, 정수에 겹친 눈금값을 더하면 측정값이에요.\n\n바깥 턱으로 외경, 안쪽 턱으로 내경, 뒤쪽 막대로 깊이까지 한 자루로 재요. 디지털 캘리퍼스도 원리는 같고요. 다만 도면 공차가 이 눈금보다 촘촘하면 캘리퍼스로는 부족해서 더 정밀한 측정기가 필요해요. 공차를 빡빡하게 적으실 땐 그걸 어떻게 확인할지도 함께 생각해보세요.\n\n정리하면, 소수점은 두 눈금이 만나는 자리에 있어요.\n\n캘리퍼스 처음 배울 때 눈금 맞추기, 헷갈리셨나요? 📏',
