    caption: '진동 많은 장비 볼트에 풀림 방지제를 바르려고 통을 집었는데, 저강도·중강도·고강도로 세 가지나 있어요. \'그냥 제일 센 걸로 바르면 되는 거 아냐?\' 싶은 순간이죠.\n\n풀림 방지제는 액체가 나사산 틈에서 굳어 진동 풀림을 막는 원리예요. 그런데 무조건 세게만 굳히면 정비 때 볼트를 못 풀어요. 그래서 일부러 세기를 나눠 둔 거예요. 저강도는 소형 나사용으로 공구로 쉽게 분해되고, 중강도는 일반 볼트용으로 힘을 주면 풀리고, 고강도는 영구 고정용이라 열을 가해야 분해돼요.\n\n그래서 \'일단 세게 바르기\'는 금물이에요. 정비로 다시 풀 볼트에 고강도를 쓰면 다음엔 열부터 가해야 하거든요. 설계할 땐 \'이 볼트를 다시 풀 일이 있나\'부터 정하고 등급을 고르세요. 조립까지 맡기실 땐 어느 볼트에 어떤 등급을 쓸지 함께 적어 주시면 좋아요.\n\n정리하면, 풀림 방지제 등급은 다시 풀 계획으로 고른다.\n\n고강도 발랐다가 못 풀어서 고생한 적, 있으신가요?',
