    caption: '기어 박스를 열어 보면 납작한 톱니, 비스듬한 톱니, 원뿔 모양, 나사처럼 생긴 것까지 있어요. 평기어, 헬리컬, 베벨, 웜… 이름도 모양도 제각각이라 처음엔 헷갈리죠.\n\n핵심은 두 축이 어떤 관계인가예요. 돌리는 축과 돌려지는 축이 나란한지, 직각으로 만나는지, 회전을 직선으로 바꿔야 하는지에 따라 기어 형태가 정해져요. 평행축이면 평기어나 헬리컬, 직각축이면 베벨이나 웜을 쓰고, 랙&피니언은 회전을 직선으로 바꿀 때, 내접기어는 컴팩트하게 꾸릴 때 골라요. 웜은 큰 감속에 유리하고 역전 방지에도 쓰이죠.\n\n같은 평행축이라도 조용함이 달라요. 헬리컬은 이가 비스듬해 평기어보다 조용히 맞물리거든요. 설계 의뢰 땐 두 축의 각도·거리와 감속비를 먼저 정리해 주시면 형태가 바로 좁혀지고, 가공 방법도 그만큼 빨리 정해져요.\n\n정리하면, 기어 형태는 축의 관계가 정한다.\n\n주변 기계에서 찾아본 기어, 어떤 종류였나요?',
