    caption: '체중은 똑같은데 운동화를 신으면 멀쩡한 마루가 뾰족한 하이힐 굽엔 자국이 남아요. 힘이 달라서가 아니라 \'닿는 면적\'이 달라서예요.\n\n면압은 힘을 닿는 면적으로 나눈 값이에요. 같은 힘이라도 좁은 면에 모이면 단위 면적당 받는 힘, 즉 면압(응력)이 커지죠. 단위는 1N/mm² = 1MPa예요. 2,000N을 10×10mm(100mm²)에 주면 20MPa, 20×20mm(400mm²)에 주면 5MPa가 돼요. 면적이 4배면 면압은 1/4로 줄어드는 거예요.\n\n볼트 머리 아래 와셔를 끼우는 진짜 이유가 바로 이거예요. 닿는 면적을 넓혀 면압을 낮추는 거죠. 연한 재료를 체결할 땐 받침 면적을 키워 자국과 변형을 막아 주세요. 설계 단계에서 받침 면을 넓게 잡아 두면 가공할 때도 그대로 반영돼요.\n\n정리하면, 힘은 면적으로 나눠서 봐야 한다.\n\n연한 재료 체결할 때, 받침 면적 어떻게 챙기시나요?',
