    caption: '구멍도 축도 도면엔 똑같이 20mm라고 적혀 있는데, 어떤 조립품은 축이 스르륵 돌고 어떤 건 프레스로 눌러야 들어가요. 같은 숫자인데 왜 이렇게 다를까요?\n\n비밀은 0.02mm 차이에 있어요. 축이 구멍보다 살짝 작으면 틈이 생겨 돌고, 살짝 크면 억지로 끼워져 고정돼요. 그 \'살짝\'이 머리카락보다 가는 차이인데 조립 성격을 완전히 바꿔 버리죠. 그래서 끼워맞춤은 세 가지로 나눠요. 돌고 미끄러지는 틈새 끼워맞춤, 압입해 고정하는 억지 끼워맞춤, 그리고 손으로 톡톡 쳐서 넣는 중간 끼워맞춤이에요.\n\n설계할 땐 치수보다 먼저 \'회전할 건지, 고정할 건지\'를 정하세요. 베어링처럼 돌아야 하면 틈새, 부시처럼 박혀 있어야 하면 억지. 도면에 H7/g6 같은 기호로 적어 주시면 가공자가 바로 알아듣고 공차를 맞춥니다.\n\n정리하면, 끼워맞춤은 치수가 아니라 목적으로 고른다.\n\n압입했다가 안 빠져서 고생한 경험, 있으신가요?',
