    caption: '같은 도면으로 같은 부품을 맡겼는데 공장마다 걸리는 시간이 두 배 차이 나고 면 상태도 달라요. 이 차이는 대체로 \'절삭조건\'이라는 세팅에서 나옵니다.\n\n절삭조건은 세 숫자의 조합이에요. 절삭속도는 날 끝이 재료를 지나는 빠르기(m/min), 이송은 한 바퀴·한 날당 나아가는 양, 절입은 한 번에 깎는 깊이. 절삭속도는 공구 수명과 열 발생을, 이송은 가공 시간과 표면 거칠기를, 절입은 한 번에 덜어내는 양을 좌우해요. 너무 빠르면 공구가 타고, 너무 느리면 시간만 낭비되죠.\n\n그리고 재질이 바뀌면 조건도 다시 잡아야 해요. 알루미늄은 빠르게, 스테인리스는 천천히 깎는 게 보통이거든요. 견적 요청하실 때 재질과 요구 면 조도를 함께 알려 주시면, 그에 맞게 조건을 제대로 잡을 수 있어서 가공비와 품질 둘 다 예측이 쉬워져요.\n\n정리하면, 절삭조건이 가공비와 품질을 가른다.\n\n조건을 잘못 잡아서 공구를 태워 본 적, 있으신가요?',
