    caption: '같은 치수로 만든 부품인데 손에 올리면 하나는 가볍고 하나는 묵직해요. 재질이 다르면 같은 부피라도 무게가 전혀 다르거든요.\n\n이걸 숫자로 나타낸 게 비중(밀도)이에요. 물을 1로 놓고 같은 부피를 저울에 올렸을 때 몇 배 무거운지 비교한 값이죠. 알루미늄은 약 2.7, 스테인리스는 약 7.9라서 같은 크기면 스테인리스가 약 3배 무겁습니다. 자주 쓰는 재질을 가벼운 순으로 늘어놓으면 ABS 1.05, 폴리카보네이트 1.2, 알루미늄 2.7, 스테인리스 7.9, 황동 8.5 순이에요. 황동이 가장 묵직한 편이죠.\n\n재질을 고를 땐 가벼움이 먼저인지 튼튼함이 먼저인지부터 정하세요. 들고 다니는 물건이면 알루미늄이나 플라스틱, 무게감과 강도가 필요하면 강이나 스테인리스 쪽이에요. 주문 전에 용도만 알려 주셔도 재질 추천이 훨씬 쉬워집니다.\n\n정리하면, 무게는 크기가 아니라 재질이 정한다.\n\n여러분은 손 느낌만으로 재질을 맞혀 본 적 있으신가요?',
    hashtags: '#비중 #밀도 #재질선택 #알루미늄',
