    caption: '3D프린터 안엔 톱니 달린 벨트가 돌고, 에어컨 실외기엔 단면이 V자인 벨트가 돌아요. 그냥 생긴 게 다른 게 아니라 맡은 역할이 달라서예요.\n\n핵심은 미끄러짐을 막느냐, 마찰로 버티느냐예요. 타이밍 벨트는 이빨이 풀리와 맞물려 어긋남 없이 동기시켜요. 그래서 위치가 정확해야 하는 프린터나 캠 구동에 쓰이죠. V벨트는 쐐기 단면이 홈에 끼며 마찰로 큰 힘을 전달해서 에어컨이나 세탁기에 들어가고요. 평벨트는 고속·저소음에 유리한 쪽이에요.\n\n부품 고를 땐 질문 세 개면 충분해요. 미끄러지면 안 되는가, 큰 힘인가, 빠른가. 위치 정밀도가 중요하면 타이밍, 힘이면 V, 속도와 조용함이면 평벨트로 보시면 됩니다. 벨트에 맞는 풀리 형상도 함께 정해지니까 설계 초반에 결정해 두는 게 좋아요.\n\n정리하면, 벨트 모양은 전달 방식의 차이다.\n\n여러분 장비엔 어떤 벨트가 돌고 있나요?',
