    caption: '두꺼운 알루미늄 플레이트를 한참 깎아서 포켓을 파냈는데, 정반에 올려 보니 가운데가 살짝 들떠 있어요. 가공이 잘못된 걸까요? 소재 상태 표시를 한번 보세요.\n\n알루미늄 뒤에 붙는 T6는 용체화 처리 후 인공시효를 거쳐 강도를 올린 상태를 말해요. 그런데 이 열처리 과정에서 소재 안에는 잔류응력, 쉽게 말해 속에 갇혀 있는 힘이 남아요. 겉이 그대로일 땐 서로 버티며 균형을 이루고 있다가, 한쪽을 많이 깎아내면 균형이 깨지면서 판이 스스로 휘어 버리는 거예요. T651은 여기에 한 단계가 더 있어요. T6 처리 뒤 소재를 살짝 잡아당기는 스트레치를 해서 그 응력을 미리 풀어 둔 거죠. 그래서 똑같이 깎아도 변형이 훨씬 적어요. 강도는 둘이 거의 같고요.\n\n그러니 부품을 설계하거나 주문하실 땐 이렇게 보시면 돼요. 얇은 부품이나 깎는 양이 적은 부품이면 T6로 충분해요. 반면 두꺼운 판을 많이 깎아내거나, 평면도가 중요한 베이스 플레이트, 크기가 큰 플레이트라면 도면 재질란에 T651까지 명시해 주세요. 가공 쪽에서 소재를 고를 때 휨 걱정을 크게 덜 수 있어요.\n\n한 줄 정리: T651은 T6에서 속에 갇힌 힘까지 풀어 둔 알루미늄이라, 많이 깎을수록 차이가 난다.\n\n여러분은 도면에 재질 표시를 어디까지 적고 계신가요?',
