    caption: '잘 돌던 펌프에서 자갈 굴러가는 듯한 소리가 나고 진동이 심해져서 뜯어 봤더니, 임펠러 날개가 곰보처럼 파여 있어요. 이게 바로 캐비테이션이에요.\n\n물은 끓는 온도가 압력에 따라 달라져요. 펌프 흡입부나 프로펠러처럼 물이 빨라지는 곳에선 압력이 떨어지는데, 그 압력이 그 온도의 증기압보다 낮아지면 물속에 작은 기포가 생겨요. 쉽게 말하면 뜨겁지 않아도 \'끓는\' 거예요. 문제는 그다음이에요. 이 기포들이 흐름을 따라 압력이 높은 곳으로 가면 순간적으로 붕괴하면서 아주 작지만 강한 충격파로 금속 표면을 때려요. 이게 끊임없이 반복되면 표면이 조금씩 파여 곰보가 되고, 소음과 진동이 늘고, 펌프 성능도 떨어져요.\n\n막는 법의 핵심은 흡입 쪽 압력에 여유를 주는 거예요. 흡입 배관은 짧고 굵게, 흡입 높이는 낮게 잡고, 필요하면 회전수를 낮추거나 액체 온도를 낮춰요. 그리고 교체용 임펠러나 케이싱 부품을 가공할 땐 유로 표면을 매끄럽게 마무리하고 날개 모서리를 도면대로 정확히 내는 게 중요해요. 거친 표면이나 단차는 그 자리에서 압력을 또 떨어뜨리거든요.\n\n한 줄 정리: 물의 압력이 증기압 밑으로 떨어지면 기포가 생기고, 그 기포가 터지며 쇠를 갉아먹는다.\n\n여러분 현장의 펌프, 요즘 이상한 소리 내고 있지 않나요?',
    hashtags: '#캐비테이션 #펌프 #임펠러 #기계고장',
