    caption: '공장 펌프실에서 다이얼 하나 돌렸을 뿐인데 모터 소리가 낮아지고 유량이 줄어드는 걸 본 적 있으신가요? 예전엔 밸브를 조여서 유량을 맞췄는데, 요즘은 모터 속도 자체를 바꿔요. 그 뒤에 있는 상자가 인버터(VFD)예요.\n\n원리는 생각보다 단순해요. 교류 모터의 회전수는 전원 주파수에 비례하거든요. 그런데 전원에서 오는 전기의 주파수는 정해져 있죠. 그래서 인버터는 들어온 교류를 일단 직류로 바꿨다가, 원하는 주파수의 교류로 다시 만들어 모터에 공급해요. 주파수를 낮추면 천천히, 높이면 빠르게. 쉽게 말하면 모터에게 \'이 박자로 돌아\' 하고 새 박자를 만들어 주는 셈이에요.\n\n펌프와 팬에서 특히 효과가 커요. 유량은 속도에 비례하지만 동력은 속도의 세제곱에 비례하거든요. 속도를 조금만 낮춰도 전력은 크게 줄어요. 게다가 천천히 가속하는 부드러운 기동 덕분에 돌입전류와 기계적 충격도 줄어서, 축이나 커플링 같은 부품에도 부담이 덜해요. 설비를 설계하거나 부품을 고를 때 밸브로 조이는 구조라면, 속도 제어로 바꿀 수 있는지 먼저 따져보세요.\n\n한 줄 정리: 인버터는 전기의 주파수를 새로 만들어 모터 속도를 다룬다.\n\n여러분 현장의 펌프와 팬, 지금 밸브로 조이고 있나요, 속도로 조절하고 있나요?',
