    caption: '기계 한 대 제어반 도면을 펼치면 센서 이름이 줄줄이 나와요. 온도 센서만 세 종류, 근접 센서도 두 종류. \'그냥 하나로 통일하면 안 되나?\' 싶으실 텐데, 여기엔 이유가 있어요.\n\n센서는 물리량을 전기 신호로 바꿔주는 번역기예요. 열, 압력, 거리, 빛, 접촉, 회전처럼 재는 대상이 다르면 번역 방식도 달라야 하죠. 같은 온도라도 열전대는 넓은 범위를, RTD(측온저항체)는 정밀하게, 서미스터는 값싸고 간단하게 재요. 압력 센서는 얇은 막(다이어프램)이 눌리는 변형을 읽고요. 근접 센서는 유도형이 금속만, 정전용량형이 비금속까지 감지해요. 광센서는 빛이 가려지는 걸, 리미트 스위치는 직접 닿는 걸, 엔코더는 회전 위치와 속도를 봐요.\n\n그래서 센서는 무엇을, 어느 거리에서, 어떤 환경에서, 얼마나 정밀하게 잴지로 골라요. 저희가 센서 브래킷이나 마운트 부품을 가공할 때 자주 묻는 게 그거예요. 센서 몸통의 나사 호칭과 감지 거리, 그리고 주변에 금속이 있는지. 이 세 가지만 정확히 주시면 브래킷 두께와 구멍 위치가 바로 정해져요.\n\n한 줄 정리: 센서 종류가 많은 건 재야 할 물리량이 그만큼 많기 때문이다.\n\n여러분 설비에서 제일 자주 말썽을 부리는 센서는 어떤 종류인가요?',
