    caption: '새 기계가 들어와 바닥에 고정하려는데 앵커볼트 카탈로그를 펼치니 종류가 한 페이지 가득. \'그냥 튼튼한 걸로 하나 주세요\'가 안 되는 이유가 있어요.\n\n앵커볼트는 콘크리트에 기계나 구조물을 붙잡아 두는 볼트예요. 크게 \'언제 심느냐\'로 나뉘어요. 콘크리트를 치기 전에 미리 묻어두는 선설치 앵커(J형·L형)는 콘크리트와 한 몸이 되어 가장 튼튼해요. 이미 굳은 바닥엔 구멍을 뚫고 넣는 후설치 앵커를 쓰는데, 이게 다시 \'어떻게 무느냐\'로 갈려요. 웨지 앵커나 세트 앵커는 구멍에 넣고 조이면 끝이 벌어지면서 콘크리트를 꽉 무는 기계식이에요. 케미컬 앵커는 접착제를 넣고 굳혀 고정하는 방식이라 진동이 많거나 가장자리에 가깝거나 하중이 클 때 유리해요.\n\n고를 땐 하중의 크기와 방향, 진동 유무, 시공 시점을 보세요. 그리고 하나 더. 어떤 앵커든 구멍 속 가루를 깨끗이 털어내지 않으면 제 힘이 안 나와요. 구멍 청소가 성능을 좌우해요. 베이스 플레이트를 가공할 때도 앵커 종류에 따라 구멍 지름과 간격이 달라지니, 앵커 사양을 먼저 정하고 도면을 그리세요.\n\n한 줄 정리: 앵커는 하중과 시공 시점으로 고르고, 구멍 청소로 완성된다.\n\n여러분 현장에선 기계 고정에 어떤 앵커를 가장 많이 쓰시나요?',
