    caption: '모터 하나 고르려고 카탈로그를 열었는데 DC 브러시, BLDC, AC 유도, 스테핑, 서보… 전기로 도는 건 다 같은데 왜 이렇게 이름이 많을까요?\n\n모터마다 잘하는 게 달라서예요. DC 브러시 모터는 구조가 간단하고 속도 제어가 쉬워 다루기 편하지만, 브러시가 닳아요. BLDC는 브러시를 없애 수명이 길고 효율이 좋고 조용한 대신 전자 드라이버가 꼭 필요해요. AC 유도모터는 단상이든 삼상이든 튼튼하고 저렴해서 공장 펌프와 팬, 컨베이어의 표준이에요. 스테핑 모터는 정해진 각도씩 딱딱 돌아서 위치 제어가 쉽고, 서보 모터는 엔코더 피드백으로 지금 어디에 있는지 계속 확인하며 정밀하게 위치와 속도를 맞춰요. CNC 공작기계와 로봇의 축이 서보로 도는 이유예요.\n\n결국 힘, 속도, 정밀도, 비용 중 무엇이 중요한지로 골라요. 그냥 돌기만 하면 되면 유도모터, 멈출 자리가 정확해야 하면 스테핑이나 서보. 모터 브래킷이나 커플링 같은 부품을 주문할 땐 모터 플랜지 치수와 축 지름, 키 홈 유무를 같이 적어주시면 한 번에 맞아요.\n\n한 줄 정리: 모터는 무엇을 얼마나 정확히 돌릴지로 고른다.\n\n여러분 장비에는 어떤 모터가 가장 많이 들어가 있나요?',
    hashtags: '#모터 #서보모터 #스테핑모터 #자동화',
