    caption: '현장에서 \'이 크레인 몇 톤짜리예요?\'라고 물으면 기사님은 대개 이렇게 답해요. \'어디까지 뻗느냐에 따라 달라요.\' 처음 들으면 좀 이상하죠. 같은 장비인데 왜 드는 힘이 날마다 달라질까요?\n\n이유는 \'무게×거리\', 즉 모멘트에 있어요. 시소를 떠올려 보세요. 가벼운 사람도 끝에 앉으면 무거운 사람을 들어 올리죠. 크레인도 짐을 멀리 뻗을수록 장비를 넘어뜨리려는 힘이 커지고, 그 힘이 전도 한계를 넘으면 그대로 넘어가요. 그래서 정격하중은 고정값이 아니라 붐 길이와 작업반경에 따라 급격히 줄어드는 값이에요. 천장 크레인, 겐트리, 지브, 타워, 이동식 모두 이 원리를 벗어나지 못합니다.\n\n부품을 양중할 때는 \'우리 짐이 몇 톤인가\'보다 \'그 반경에서 몇 톤까지 허용되는가\'를 먼저 봐야 해요. 그게 하중표(로드차트)이고, 기준은 아웃트리거를 완전히 펼친 상태예요. 저희도 무거운 가공물을 반입·출고할 때 짐 무게와 놓을 위치를 같이 알려드리면 양중 계획이 훨씬 안전하게 잡힙니다.\n\n한 줄 정리: 크레인의 힘은 무게가 아니라 반경이 정한다.\n\n여러분 현장의 크레인, 하중표 보고 쓰고 계신가요? 🏗️',
