    caption: '비행기 창가 자리에 앉으면 날개 위에 작은 점이 줄지어 박혀 있는 게 보여요. 전부 리벳이죠. 철골 구조물은 용접으로 붙이는데, 왜 비행기는 굳이 구멍을 뚫고 하나하나 리벳을 박을까요?\n\n리벳이음은 구멍을 뚫고 리벳을 끼운 뒤 머리를 눌러 성형해서 두 판을 꽉 붙드는 방식이에요. 핵심은 열을 가하지 않는다는 점이에요. 용접은 재료를 녹여 붙이기 때문에 강하고 기밀도 좋고 가볍고 빠르지만, 녹았다 굳은 주변(열영향부)의 성질이 변하고 판이 뒤틀리기 쉬워요. 속에 생긴 결함은 눈으로 안 보여서 별도 검사도 필요하죠. 알루미늄 동체는 얇아서 열 변형을 잡기 어렵고, 리벳은 겉에서 상태를 바로 볼 수 있어 점검에 유리해요. 알루미늄 같은 이종 재료끼리 붙일 수 있다는 것도 큰 장점입니다.\n\n부품을 설계하거나 주문하실 땐 \'어떤 이음이 더 센가\'만 보지 말고 \'재료가 열에 어떻게 반응하는지\', \'나중에 누가 어떻게 점검하는지\'를 같이 보세요. 알루미늄 얇은 판 조립이면 리벳이나 볼트 체결을 먼저 떠올리시고, 철 구조물이나 배관처럼 기밀이 중요하면 용접이 자연스러워요.\n\n한 줄 정리: 이음 방식은 강도보다 재료와 점검이 정한다.\n\n여러분 제품엔 리벳과 용접, 어느 쪽이 더 많나요? ✈️',
