    coverArt: 'flowmeter_types',
    slides: [
      { type: 'body', chip: '관찰', h: '같은 \'유량\'인데<br>계기는 제각각', d: '배관실 하나에도 조임판이 든 것, 매끈한 관, 배관 밖에 붙인 센서까지 모양이 다 달라요. 재는 양은 같은데 왜 이럴까요?' },
      { type: 'answer', chip: '결론', h: '유체와 설치 조건이<br>방식을 정해요', d: '유량을 직접 세는 게 아니라 압력, 전기, 소리, 회전 같은 \'흔적\'으로 계산해요. 어떤 흔적이 잘 잡히느냐는 유체와 배관마다 다르죠.' },
      { type: 'list', chip: '대표 방식', h: '흔적을 읽는<br>여섯 가지 방법', items: ['차압식: 좁힌 앞뒤 압력차로 계산', '전자식·초음파식: 관을 막지 않음', '터빈·와류·면적식: 회전·소용돌이·눈'] },
      { type: 'body', chip: '실무', h: '정확도만 보지 말고<br>압력 손실도 보세요', d: '차압식은 단순하지만 압력 손실이 있고, 전자식은 도전성 액체만 돼요. 초음파식은 배관을 안 건드려 기존 라인에 유리하죠. <b>유체·정확도·설치</b>로 고르세요.' },
      { type: 'answer', chip: '한 줄 정리', h: '유량계는 유체가<br>남긴 흔적을 읽는다' },
    ],
    caption: '공장 배관실에 가 보면 유량계만 해도 모양이 제각각이에요. 관 사이에 얇은 판이 끼워진 것, 안이 매끈하게 뚫린 것, 아예 배관 바깥에 센서만 붙여 둔 것까지. 다 같은 \'유량\'을 재는데 왜 이렇게 여러 방식일까요?\n\n유량계는 흐르는 양을 직접 세는 게 아니라 유체가 남기는 \'흔적\'을 읽어 계산해요. 차압식은 오리피스로 관을 좁혀 앞뒤 압력차를 재는 방식이라 단순하지만 그만큼 압력 손실이 생겨요. 전자식은 도전성 액체만 잴 수 있는 대신 관 안에 장애물이 없어 압력 손실이 없고, 초음파식은 배관 밖에서 재니 배관을 건드리지 않아요. 터빈식은 날개의 회전수, 와류식은 장애물 뒤에 생기는 소용돌이의 빈도를 세고, 면적식(로터미터)은 눈으로 직접 보는 가장 소박한 방식이죠.\n\n계기를 고를 땐 정확도 숫자만 보지 마세요. 유체 종류(물인지 기름인지, 전기가 통하는지), 허용 가능한 압력 손실, 설치 공간, 기존 배관을 자를 수 있는지까지 같이 보셔야 해요. 저희처럼 계기 몸체나 플랜지, 오리피스 판을 가공하는 입장에서도 \'어떤 방식의 계기인지\'를 알아야 내경과 면 거칠기를 어디까지 챙길지 정할 수 있거든요.\n\n한 줄 정리: 유량계는 유체가 남긴 흔적을 읽는 장치다.\n\n여러분 현장엔 어떤 방식의 유량계가 제일 많으신가요? 💧',
