    caption: '공장 천장을 따라가는 배관을 보면 어떤 곳은 볼트로 꽉 물려 있고, 어떤 곳은 그냥 걸쳐만 놓은 것처럼 보여요. 처음엔 \'왜 여긴 대충 했지?\' 싶지만, 알고 보면 일부러 그렇게 둔 거예요.\n\n배관은 뜨거운 유체가 지나면 길이 방향으로 늘어나고, 식으면 다시 줄어요. 이걸 전부 꽉 고정해 버리면 늘어날 곳이 없는 배관은 옆으로 휘거나, 힘이 가장 약한 플랜지 이음부에서 새기 시작해요. 그래서 지지대는 역할별로 나뉘어요. 앵커는 완전히 고정해 움직임의 기준점이 되고, 가이드는 옆 방향만 잡고 길이 방향은 자유롭게 놓아줘요. 행거는 위에서 매달고 서포트는 아래서 받치며, 온도 변화로 오르내리는 구간엔 스프링 행거가 탄력 있게 받쳐 주죠.\n\n배관 라인을 설계하거나 지지대 부품을 주문하실 땐 \'어디서 잡고 어디로 보낼지\'를 먼저 그려 보세요. 앵커를 기준으로 늘어나는 방향을 정하고, 그 길 위의 지지대는 미끄러질 수 있게 두는 거예요. 가이드나 앵커 브래킷을 가공할 땐 접촉면의 마감과 틈새가 움직임을 좌우하니, 도면에 \'고정\'인지 \'미끄럼\'인지만 적어 주셔도 훨씬 정확하게 만들어 드릴 수 있어요.\n\n한 줄 정리: 배관은 잡을 곳과 놓아줄 곳을 나눠서 받친다.\n\n플랜지가 자꾸 새는 곳이 있다면, 혹시 다 꽉 잡고 계신 건 아닐까요? 🔧',
