    caption: '공장 전기요금 고지서를 보다가 \'역률\'이라는 항목에서 멈춰 본 적 있으신가요? 낮으면 할증이 붙고 높으면 깎아 준다는데, 대체 뭘 재는 숫자일까요?\n\n맥주잔을 떠올리면 쉬워요. 잔에는 마실 수 있는 맥주와 자리만 차지하는 거품이 같이 담겨 있죠. 전기도 비슷해요. 실제로 일을 한 전력이 유효전력(맥주), 공급은 됐지만 일을 안 한 전력이 무효전력(거품), 둘을 합친 잔 전체가 피상전력이에요. 역률은 그중 진짜 맥주의 비율, 즉 유효전력 나누기 피상전력이죠. 거품은 왜 생길까요? 모터나 변압기처럼 코일이 들어간 부하는 전류가 전압보다 늦게 따라와요. 그 늦은 만큼 일을 안 하는 전류가 생기고, 같은 일을 하는데도 전류가 더 흘러야 하니 전선과 변압기를 더 굵고 크게 준비해야 해요. 그래서 역률이 낮으면 요금이 할증되는 거예요.\n\n해결책은 비교적 단순해요. 코일과 반대 성질을 가진 콘덴서를 달아 거품을 걷어내는 거죠. 모터가 많은 공장이라면 설비를 늘릴 때 역률부터 확인해 보세요. 저희도 가공 설비를 증설할 때 분전반의 콘덴서를 같이 점검하는데, 요금뿐 아니라 전선과 차단기 부담까지 줄어들어요.\n\n한 줄 정리: 역률은 공급한 전기 중 진짜 일한 비율이다.\n\n여러분 공장 고지서의 역률, 마지막으로 확인하신 게 언제인가요? 🍺',
