    caption: '모터 하나 돌리는 작은 드라이버 기판을 들여다보면 다이오드와 트랜지스터가 꼭 짝으로 붙어 있어요. 하나로는 안 되는 걸까요?\n\n둘은 하는 일이 완전히 달라요. 다이오드는 전류를 한 방향으로만 통과시키는 체크밸브예요. 그래서 교류를 직류로 바꾸는 정류, 전원을 거꾸로 꽂았을 때 막아 주는 역전압 보호에 쓰이고, 빛을 내는 LED도 사실 다이오드의 한 종류죠. 트랜지스터는 작은 신호로 큰 전류를 켜고 끄거나 키우는 수도꼭지예요. BJT와 MOSFET이 대표 선수예요. 그런데 모터는 코일이라 전류를 끊는 순간 역기전력이 크게 튀어요. 이 전압이 트랜지스터를 망가뜨리지 않도록 옆에 환류 다이오드를 달아 튀는 에너지를 흘려보내 줘요. 트랜지스터가 돌리고, 다이오드가 지키는 구조인 셈이에요.\n\n소형 자동화 장치나 치구에 모터를 붙이실 땐 \'어떻게 켜고 끌지\'만 생각하지 마시고 \'끌 때 튀는 전압은 어디로 보낼지\'도 꼭 챙기세요. 릴레이나 솔레노이드처럼 코일이 든 부품엔 거의 예외 없이 환류 다이오드가 따라붙어요. 드라이버 보드를 넣는 하우징을 가공할 땐 발열을 생각해 방열판 자리와 공기 통로를 미리 잡아 두시면 좋아요.\n\n한 줄 정리: 트랜지스터가 돌리고 다이오드가 지킨다.\n\n여러분은 모터 끄다가 뭔가 태워 먹은 경험, 있으신가요? 💡',
