    caption: '가공 중에 갑자기 기계가 멈추고 불이 꺼져요. 분전반에서 차단기를 올리면 다시 돌아가니 대개 그걸로 끝이죠. 그런데 차단기가 떨어지는 이유는 세 가지고, 각각 위험의 종류가 달라요.\n\n첫째는 과부하예요. 정격보다 많은 전류가 오래 흐르면서 전선이 서서히 뜨거워지는 상황으로, 멀티탭 하나에 히터와 공구를 잔뜩 꽂았을 때가 전형이에요. 둘째는 단락, 흔히 합선이라고 부르죠. 두 선이 직접 붙어 순간적으로 아주 큰 전류가 흐르고, 불꽃과 화재로 이어질 수 있어요. 셋째는 지락이에요. 전류가 원래 길을 벗어나 땅이나 기기 외함으로 새어 나가는 것으로, 사람이 그 외함을 만지면 감전될 수 있습니다. 차단기도 역할이 나뉘어요. 배선용 차단기는 과부하와 단락을 잡고, 누전차단기는 새어 나가는 전류, 즉 지락을 잡습니다.\n\n제어반이나 장비 프레임 부품을 설계·주문할 땐 두 종류 차단기가 들어갈 자리와 함께 접지 경로를 꼭 챙겨 주세요. 도장이나 아노다이징 위에 접지 단자를 올리면 전기가 통하지 않으니, 접지 자리는 가공면을 노출하거나 별도 단자를 두는 식으로 도면에 표시해 두는 게 좋아요.\n\n한 줄로 정리하면, 차단기가 떨어졌다면 올리기 전에 \'왜\'부터 물어야 해요.\n\n여러분 현장에서 가장 자주 떨어지는 차단기, 원인은 셋 중 뭐였나요?',
    hashtags: '#차단기 #과부하 #누전 #전기안전',
