    caption: '배관 라인에 플랜지 두 장을 맞댔는데 볼트 구멍이 미묘하게 어긋나요. 호칭 지름은 분명 같은데요. 확인해 보니 한쪽은 Class 150, 다른 쪽은 PN 16. 같은 \'플랜지\'인데 왜 이런 일이 생길까요?\n\n플랜지 규격은 뿌리가 다른 두 체계가 나란히 쓰여요. ASME Class(150·300·600…)는 미국계 인치 기반으로, 온도에 따라 허용 압력이 달라지는 \'압력-온도 등급\'이에요. 같은 Class 300이라도 뜨거운 유체에서는 견딜 수 있는 압력이 낮아지죠. PN(10·16·25·40)은 유럽·ISO계 mm 기반으로, bar를 기준으로 한 호칭압력이에요. 숫자의 뜻부터 다르고, 호칭 지름이 같아도 외경, 볼트 구멍 수와 위치가 달라서 맞대면 맞지 않습니다. 같은 사이즈 신발이라도 나라마다 치수 체계가 다른 것과 비슷해요.\n\n플랜지를 설계하거나 가공 주문하실 땐 규격 체계(Class인지 PN인지), 등급, 호칭 지름, 면 형태까지 한 세트로 적어 주세요. 상대 배관의 규격을 먼저 확인하는 게 가장 빠르고, 두 체계를 한 라인에 섞어 쓰는 건 피해야 합니다.\n\n한 줄로 정리하면, 플랜지는 크기보다 규격 체계를 먼저 맞춰야 해요.\n\n현장에서 규격이 달라 안 맞았던 부품, 플랜지 말고 또 뭐가 있었나요?',
