    caption: '볼트 머리를 자세히 보신 적 있나요? 8.8, 10.9 같은 숫자가 작게 찍혀 있어요. 장식이 아니라 이 볼트가 얼마나 버티는지 알려주는 이름표예요.\n\n읽는 법은 생각보다 간단해요. 앞 숫자에 100을 곱하면 인장강도, 즉 끊어지기 직전까지 버티는 힘이에요. 10.9라면 약 1000MPa죠. 뒤의 .9는 항복강도가 인장강도의 90%라는 뜻이라, 900MPa를 넘기면 볼트가 영구적으로 늘어나기 시작해요. 같은 식으로 8.8은 800/640MPa, 12.9는 1200/1080MPa로 가장 강한 등급이에요. 스테인리스 볼트는 A2-70처럼 표기가 다른데, 뒤의 70이 인장강도 700MPa를 뜻해요.\n\n부품을 주문하거나 조립 도면을 그릴 땐 볼트 등급과 너트 등급을 짝으로 보세요. 10.9 볼트엔 10등급 너트처럼요. 등급이 올라가면 조임 토크도 커지니, 토크값도 등급에 맞춰 지정해야 체결부가 제 힘을 내요.\n\n한 줄 정리: 볼트의 숫자는 그 볼트가 버티는 힘의 이름표예요.\n\n여러분 공구함의 볼트엔 어떤 숫자가 찍혀 있나요?',
