    caption: '공구함을 열어 보면 토크렌치만 서너 가지가 있는 걸 보신 적 있을 거예요. 딸깍 소리 나는 것, 바늘이 눈금을 가리키는 것, 화면에 숫자가 뜨는 것까지. 다 같은 일을 하는데 왜 이렇게 여럿일까요?\n\n정해진 힘으로 볼트를 조인다는 목적은 같지만, 그 힘을 사용자에게 \'알려주는 방식\'이 달라요. 클릭식은 설정한 토크에 도달하면 딸깍 소리가 나서 가장 흔하게 쓰여요. 빔식은 막대가 휘면서 바늘이 눈금을 가리키는 구조라 단순하고 고장이 거의 없죠. 다이얼식은 정밀하게 값을 읽을 때, 디지털식은 값 표시에 각도와 기록까지 필요할 때 골라요. 쉽게 말하면 빠르게 조일지, 정밀하게 잴지, 남겨 둘지에 따라 공구가 나뉘는 셈이에요.\n\n현장에서 한 가지만 기억하세요. 클릭식은 쓰고 나면 최저값으로 풀어 보관해야 스프링이 눌린 채 변형되지 않고, 주기적인 교정도 필요해요. 과토크는 나사산을 망가뜨리고 저토크는 풀림을 부르니, 부품을 조립할 땐 도면에 적힌 지정 토크를 꼭 확인하는 게 좋아요.\n\n한 줄 정리: 토크렌치가 여럿인 건 힘을 알려주는 방식이 다르기 때문이에요.\n\n여러분은 어떤 방식의 토크렌치를 가장 자주 쓰시나요?',
